import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../../core/services/auth.service';
import { NotificationService } from '../../../core/services/notification.service';
import { HistoryService } from '../../../core/services/history.service';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html'
})
export class LoginComponent {

  // The FormGroup holds all form controls and their validators
  loginForm: FormGroup;
  errorMessage = '';
  isLoading = false;
  showPassword = false;

  constructor(
    private fb: FormBuilder,          // FormBuilder creates FormGroups cleanly
    private authService: AuthService,
    private historyService: HistoryService,
    private notifService: NotificationService,
    private router: Router
  ) {
    // Build the form — each key maps to an <input formControlName="...">
    this.loginForm = this.fb.group({
      username: ['', [Validators.required]],
      password: ['', [Validators.required]]
    });
  }

  // Convenience getters — used in the template as  f['username'].errors
  get f() { return this.loginForm.controls; }

  onSubmit(): void {
    this.errorMessage = '';

    // Mark all fields as touched so validation errors appear on submit
    this.loginForm.markAllAsTouched();
    if (this.loginForm.invalid) return;

    this.isLoading = true;

    this.authService.login(this.loginForm.value).subscribe({
      next: (res) => {
        this.notifService.show(`Welcome back, ${res.username}!`, 'success');
        this.historyService.loadFromServer().subscribe();
        this.router.navigate(['/measure']);
      },
      error: (err) => {
        this.errorMessage = err.error?.message || 'Invalid username or password.';
        this.isLoading = false;
      }
    });
  }

  togglePassword(): void {
    this.showPassword = !this.showPassword;
  }
}
<div id="auth-screen">
  <div class="auth-wrapper">

    <!-- Left decorative panel -->
    <div class="auth-left">
      <div class="auth-illustration">📐</div>
      <div class="auth-brand">Quantity Measurement</div>
      <div class="auth-tagline">Precision tools for length, weight,<br>volume &amp; temperature.</div>
    </div>

    <!-- Right form panel -->
    <div class="auth-right">

      <!-- Tabs — routerLink switches between Login and Signup pages -->
      <div class="auth-tabs">
        <button class="auth-tab active">Login</button>
        <button class="auth-tab" routerLink="/auth/signup">Signup</button>
      </div>

      <!-- [formGroup] binds this form element to the loginForm FormGroup -->
      <form class="auth-form active" [formGroup]="loginForm" (ngSubmit)="onSubmit()">

        <!-- Username field -->
        <div class="form-group">
          <label class="form-label">Username or Email</label>
          <input
            class="form-input"
            type="text"
            placeholder="Your username or email"
            formControlName="username"
            [class.is-invalid]="f['username'].invalid && f['username'].touched"
          />
          <!-- Show error only after the user has touched this field -->
          <small class="field-error" *ngIf="f['username'].invalid && f['username'].touched">
            Username is required.
          </small>
        </div>

        <!-- Password field with show/hide toggle -->
        <div class="form-group">
          <label class="form-label">Password</label>
          <div class="form-input-wrap">
            <input
              class="form-input"
              [type]="showPassword ? 'text' : 'password'"
              placeholder="Your password"
              formControlName="password"
              style="padding-right: 40px"
              [class.is-invalid]="f['password'].invalid && f['password'].touched"
            />
            <button type="button" class="toggle-pw" (click)="togglePassword()">
              {{ showPassword ? '🙈' : '👁' }}
            </button>
          </div>
          <small class="field-error" *ngIf="f['password'].invalid && f['password'].touched">
            Password is required.
          </small>
        </div>

        <!-- API error message (wrong credentials etc.) -->
        <div class="auth-error" *ngIf="errorMessage" style="display:block">
          {{ errorMessage }}
        </div>

        <button
          type="submit"
          class="btn-primary"
          style="background:#3d5af1; box-shadow:0 4px 12px rgba(61,90,241,0.3)"
          [disabled]="isLoading"
        >
          {{ isLoading ? 'Logging in...' : 'Login' }}
        </button>

        <div style="text-align:center;margin:15px 0;color:var(--muted);font-size:12px;font-weight:600">OR</div>

        <!-- Google OAuth — links directly to the C# backend -->
        <a href="https://localhost:5000/api/v1/auth/google"
           class="btn-primary"
           style="background:#fff;color:#333;border:1px solid #ddd;display:flex;align-items:center;justify-content:center;text-decoration:none;gap:10px;box-shadow:none">
          <svg width="18" height="18" viewBox="0 0 24 24">
            <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
            <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
            <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"/>
            <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/>
          </svg>
          Continue with Google
        </a>

        <p style="text-align:center;margin-top:16px;font-size:13px;color:var(--muted)">
          Don't have an account?
          <a routerLink="/auth/signup" style="color:var(--primary);font-weight:600;text-decoration:none">Sign up</a>
        </p>

      </form>
    </div>
  </div>
</div>
